mapper.select:
select m.*,s.realname as createname,o.ORGNAME as linkOrgName from TBL_RISK_MONITORINGFILL m left join tbl_staff s on s.staffid=m.CREATESTAFFID left join tbl_organization o on o.orgid=m.LINKORGID left join TBL_FILL_ISSUED iss on iss.fillid=m.id where 1=1
and riskyear LIKE concat(concat('%',#{queryParam.riskyear} ),'%')
and quartername LIKE concat(concat('%',#{queryParam.quartername} ),'%')
and m.CREATESTAFFID=#{queryParam.createstaffid}
and linkOrgId=#{queryParam.linkOrgId}
and reportstatus is null or reportstatus=0
and reportstatus=1
and reportstatus=2
${sql}
order by m.id desc

	 select f.*,iss.DEPTNOTES from TBL_RISK_MONITORINGFILL f 
    left join TBL_FILL_ISSUED iss on iss.FILLID=f.id
     where riskyear=#{year} and quartername=#{jd} and linkorgid=#{orgid}
     and TO_CHAR( f.createtime, 'YYYY-MM-DD')=(select max(TO_CHAR(createtime, 'YYYY-MM-DD'))
     from TBL_RISK_MONITORINGFILL where riskyear=#{year} and quartername=#{jd} and linkorgid=#{orgid})
     and status=6
